crypto_script:
// ================= 运营商 → 账号后缀映射（可按门户要求自行增删改） =================
// 方案的「运营商」字段取值：预设 移动 / 联通 / 电信；选「自定义」时是输入的关键字。
// 映射不到的值按「关键字 → @关键字」处理（已带 @ 则原样使用）；账号为空不追加。
var ISP_SUFFIX = {
  "移动": "@cmcc",
  "联通": "@unicom",
  "电信": "@telecom",
  "校园网": "@xyw"
};

// ================= Dr.COM eportal（dr1003，encrypt=1）字段加密 =================
// 密钥 = 本机 IP 逐字符异或；各字段字符再与密钥异或后转两位十六进制。
function xorHex(str, key) {
  var out = "";
  for (var i = 0; i < str.length; i++) {
    var x = str.charCodeAt(i) ^ key;
    out += (x < 16 ? "0" : "") + x.toString(16);
  }
  return out;
}
function transform(ctx) {
  var ip = ctx.local_ip || "";
  if (!ip) {
    throw new Error("无法获取本机 IP（ctx.local_ip 为空），请确认已连接校园网");
  }
  var key = 0;
  for (var i = 0; i < ip.length; i++) {
    key ^= ip.charCodeAt(i);
  }

  var suffix = "";
  var isp = (ctx.isp || "").trim();
  if (isp) {
    suffix = ISP_SUFFIX[isp] !== undefined ? ISP_SUFFIX[isp] : (isp.charAt(0) === "@" ? isp : "@" + isp);
  }
  // 账号里已含 @（手动写后缀的旧用法）时不再追加，避免出现 @cmcc@cmcc
  var user = ctx.username || "";
  if (user.indexOf("@") >= 0) suffix = "";

  return {
    callback: xorHex("dr1003", key),
    login_method: xorHex("1", key),
    user_account: xorHex(",0," + user + suffix, key),
    user_password: xorHex(ctx.password || "", key),
    wlan_user_ip: xorHex(ip, key),
    wlan_user_ipv6: "",
    wlan_user_mac: "",
    wlan_ac_ip: "",
    wlan_ac_name: "",
    jsVersion: xorHex("4.2.1", key),
    terminal_type: xorHex("1", key),
    lang: xorHex("zh-cn", key),
    v: String(Math.floor(Math.random() * 9000) + 1000)
  };
}
